import numpy as np

def sigmoid(x):
    x_clipped = np.clip(x, -500, 500)
    return 1 / (1 + np.exp(-x_clipped))

def relu(x):
    return np.maximum(0, x)

def tanh(x):
    return np.tanh(x)

def softmax(x):
    exp_x = np.exp(x - np.max(x, axis=-1, keepdims=True))
    return exp_x / np.sum(exp_x, axis=-1, keepdims=True)

def activation_forward(x, name='relu'):
    activations = {
        'sigmoid': sigmoid,
        'relu': relu,
        'tanh': tanh,
        'softmax': softmax
    }
    return activations[name](x)

if __name__ == "__main__":
    x = np.array([-1, 0, 1])
    print("Sigmoid:", sigmoid(x))
    print("ReLU:", relu(x))
    print("Tanh:", tanh(x))
    print("Softmax:", softmax(x))

import numpy as np

def step_decay(initial_lr, epoch, drop_factor=0.5, epochs_drop=30):
    return initial_lr * (drop_factor ** (epoch // epochs_drop))

def cosine_annealing(initial_lr, epoch, T_max, lr_min=0):
    if epoch >= T_max:
        return lr_min
    return lr_min + 0.5 * (initial_lr - lr_min) * (1 + np.cos(np.pi * epoch / T_max))

def warmup_cosine(initial_lr, epoch, warmup_epochs=5, T_max=100, lr_min=1e-6):
    if epoch < warmup_epochs:
        return initial_lr * (epoch + 1) / warmup_epochs
    effective_epoch = epoch - warmup_epochs
    effective_T = T_max - warmup_epochs
    return cosine_annealing(initial_lr, effective_epoch, effective_T, lr_min)

def plot_lr_schedule(initial_lr=0.01, total_epochs=120):
    """模拟不同的学习率调度曲线"""
    schedules = {'step': [], 'cosine': [], 'warmup_cosine': []}
    for epoch in range(total_epochs):
        schedules['step'].append(step_decay(initial_lr, epoch, 0.5, 30))
        schedules['cosine'].append(cosine_annealing(initial_lr, epoch, 120, 0))
        schedules['warmup_cosine'].append(warmup_cosine(initial_lr, epoch, 5, 120))
    return schedules

if __name__ == "__main__":
    print("Epoch 0 step:", step_decay(0.01, 0))
    print("Epoch 30 step:", step_decay(0.01, 30))
    print("Epoch 60 step:", step_decay(0.01, 60))
    print("Epoch 0 cosine:", cosine_annealing(0.01, 0, 120))
    print("Epoch 60 cosine:", round(cosine_annealing(0.01, 60, 120), 6))
    print("Epoch 120 cosine:", cosine_annealing(0.01, 120, 120))
